def paginate(items, page_size):
    if page_size < 1:
        raise ValueError("page_size must be positive")
    return [items[offset:offset + page_size] for offset in range(0, len(items), page_size)]

def calculate_discount_cents(subtotal_cents, discount_percent):
    if subtotal_cents < 0 or not 0 <= discount_percent <= 100:
        raise ValueError("invalid order discount")
    return (subtotal_cents * discount_percent + 50) // 100


def amount_due_cents(subtotal_cents, discount_percent):
    return subtotal_cents - calculate_discount_cents(subtotal_cents, discount_percent)

from pricing import amount_due_cents, calculate_discount_cents


def _money(cents):
    return f"${cents // 100}.{cents % 100:02d}"


def render_receipt(subtotal_cents, discount_percent):
    discount = calculate_discount_cents(subtotal_cents, discount_percent)
    due = amount_due_cents(subtotal_cents, discount_percent)
    return (
        f"Subtotal: {_money(subtotal_cents)}\n"
        f"Discount ({discount_percent}%): -{_money(discount)}\n"
        f"Amount due: {_money(due)}\n"
    )

import time


class ExpiringCache:
    def __init__(self, ttl_seconds, clock=None):
        if ttl_seconds < 0:
            raise ValueError("ttl_seconds must not be negative")
        self.ttl_seconds = ttl_seconds
        self.clock = clock or time.monotonic
        self._entries = {}

    def put(self, key, value):
        self._entries[key] = (value, self.clock())

    def get(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return None
        value, stored_at = entry
        if self.clock() - stored_at >= self.ttl_seconds:
            del self._entries[key]
            return None
        return value

def resolve_settings(defaults, project_values, environment):
    resolved = {}
    resolved.update(defaults)
    resolved.update(project_values)
    resolved.update(environment)
    return resolved
